const { PrismaClient } = require('@prisma/client')
const prisma = new PrismaClient()

async function main() {
  const invoices = await prisma.invoice.findMany({
    include: {
      _count: {
        select: { invoiceItems: true }
      }
    }
  })
  console.log('=== Invoices and Item Counts ===')
  invoices.forEach(inv => {
    console.log(`Invoice ID: ${inv.id}, InvoiceNo: ${inv.invoiceNo}, Items count: ${inv._count.invoiceItems}, Grand Total: ${inv.grandTotal}`)
  })
}

main()
  .catch(console.error)
  .finally(() => prisma.$disconnect())
